def page(p,standalone=False):
 c=CONTENT[p['id']]; name=p['name']; asset='.' if standalone else '../..'; home='https://theinternetishard.coolchant.chatgpt.site/' if standalone else '../../index.html'
 primary='https://trigger.fish/' if p['id']=='triggerfish' else '#get-started'
 primary_label='Visit trigger.fish ↗' if p['id']=='triggerfish' else 'Get started ↓'
 feature_html=''.join(f'<article><span class="feature-number">0{i+1}</span><h3>{E(h)}</h3><p>{E(t)}</p></article>' for i,(h,t) in enumerate(c['features']))
 workflow=''.join(f'<li><span>0{i+1}</span><div><h3>{E(h)}</h3><p>{E(t)}</p></div></li>' for i,(h,t) in enumerate(c['steps']))
 links=''.join(f'<a class="resource" href="{E(u,quote=True)}">{E(t)} <span>↗</span></a>' for t,u in c['links'])
 related=''.join(f'<a href="{(home+"projects/"+rid+"/index.html") if standalone else "../"+rid+"/index.html"}"><span>{E(next(x["name"] for x in projects if x["id"]==rid))}</span> ↗</a>' for rid in c['related'])
 logo=f'<img class="project-logo" src="{asset}/protomire.png" width="4096" height="1075" alt="Protomire">' if p['id']=='protomire' else f'<span class="project-wordmark">{E(name)}</span>'
 return f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(name)} — The Internet Is Hard</title><meta name="description" content="{E(c['lead'],quote=True)}"><link rel="stylesheet" href="{asset}/style.css"><link rel="stylesheet" href="{asset}/project.css"><link rel="icon" href="{asset}/favicon.svg"></head><body class="project-page"><a class="skip" href="#overview">Skip to project</a><header><a class="brand" href="{home}"><span class="brand-icon">⌘</span> the internet is hard.</a><nav aria-label="Project navigation"><a href="#features">Features</a><a href="#workflow">How it works</a><a href="#get-started">Get started</a><a href="{home}#projects">All projects ↗</a></nav></header><main><section class="project-hero" id="overview"><a class="breadcrumb" href="{home}#projects">← THE OPEN WORKBENCH</a><div class="project-heading"><div><p class="eyebrow">{E(p['tag'])} / {E(p['kind'].upper())}</p><h1>{E(c['headline'])}</h1><p class="project-lead">{E(c['lead'])}</p><div class="actions"><a class="button dark" href="{primary}">{primary_label}</a><a class="text-link" href="{E(p['url'],quote=True)}">{'Source code' if p['kind']=='github' else 'Hugging Face'} ↗</a></div></div><aside class="project-identity">{logo}<span class="identity-rule"></span><p>{E(c['audience'])}</p><span class="eyebrow">A PROJECT BY GREG HAVENS</span></aside></div></section><section class="project-features" id="features"><div class="section-top"><div><p class="eyebrow">THE PROJECT, IN PRACTICE</p><h2>What you can do with it.</h2></div></div><div class="feature-grid">{feature_html}</div></section><section class="project-workflow" id="workflow"><div><p class="eyebrow">FROM IDEA TO USE</p><h2>How it works.</h2><ol>{workflow}</ol></div><div class="example-panel"><div class="windowbar">{E(c['example_title'])}</div><pre><code>{E(c['example'])}</code></pre><p>{E(c['example_note'])}</p></div></section><section class="project-start" id="get-started"><div><p class="eyebrow">TAKE IT FOR A SPIN</p><h2>Start here.</h2><p>{E(c['start'])}</p><div class="status-box"><span class="eyebrow">STATUS & REQUIREMENTS</span><p>{E(c['status'])}</p></div></div><div class="resource-list">{links}<a class="resource" href="{E(p['url'],quote=True)}">{'Browse source on GitHub' if p['kind']=='github' else 'Repository files & documentation'} <span>↗</span></a></div></section><section class="related"><p class="eyebrow">ELSEWHERE IN THE WORKBENCH</p><h2>Keep exploring.</h2><div>{related}</div></section></main><footer><a class="brand" href="{home}">the internet is hard.</a><span>Backwoods Models & Protomire · Greg Havens</span><a href="{home}#projects">All projects ↑</a></footer></body></html>'''
CONTENT['biff']=dict(headline='A judgment your code can act on.',lead='Biff is an upcoming open-weight System One model. Supply context and typed questions; get probabilities over the answers you define.',audience='For builders who need classification, routing, scoring, or condition checks as structured model outputs.',features=[('Choice','Ask a question with named options and receive a probability distribution over those options.'),('Score','Define an ordered scale and get a distribution over its levels, together with an expected score.'),('Condition','Ask whether a stated condition holds and receive its probability.'),('One state, many questions','The design reads a shared state and answers multiple typed questions against that context without generating a text answer.')],steps=[('Provide context','Send the state you want to evaluate, such as a support ticket or document.'),('Define the judgment','Choose the question type and supply criteria or allowed options.'),('Use the probabilities','Threshold, route, or rank using the structured output in your application.')],example_title='Illustrative ticket-routing result',example='Question: Which team should handle this ticket?\n\nBilling     0.91\nTechnical   0.07\nSales       0.02',example_note='Illustrative probabilities only. This page does not call a live Biff model.',start='Biff is still in development. Weights are planned for Hugging Face under Apache 2.0. There is no released download or public inference endpoint to try yet.',links=[('Ask about Biff','mailto:greg@theinternetishard.com?subject=Biff'),('Greg on Hugging Face','https://huggingface.co/greghavens')],status='Upcoming model. Release timing and measured production performance have not been announced here. Planned licensing describes intent, not an already available release.',related=['jev-graph-builder','jev-no-bullshit','protomire'])
